const safe=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const cliProviders=[['claude','Claude Code'],['codex','Codex'],['cursor','Cursor Agent'],['antigravity','Antigravity']];
export function accountOptions(data,provider,selected=''){return `<option value="">System sign-in</option>`+(data.providerAccounts||[]).filter(a=>a.provider===provider).map(a=>`<option value="${a.id}" ${a.id===selected?'selected':''}>${safe(a.name)}${a.verified?'':' · sign-in needed'}</option>`).join('');}
export function accountField(data,provider,selected='',name='accountId'){return `<label class="form-field"><span>Account</span><select name="${name}">${accountOptions(data,provider,selected)}</select></label>`;}
export function computerNotice(data){const pending=data.computerRequests||[];return pending.length?`<div class="notice approval-notice"><strong>${pending.length} approval request${pending.length===1?'':'s'} waiting for your approval</strong><button class="btn primary" data-workflow="computer-approvals">Review requests</button></div>`:'';}
export function projectWorkflow(data,p){if(!p)return '';return `<div class="notice workflow-bar"><span><strong>${data.tasks.filter(t=>t.status==='running').length} / ${data.maxConcurrentTasks||10} task slots in use</strong><br>Orchestrator: ${safe(cliProviders.find(x=>x[0]===(p.orchestratorProvider||'claude'))?.[1])}${p.autoOrchestrate?' · automatic review enabled':''}</span><button class="btn primary" data-workflow="run-ready">Start ready workers</button><button class="btn" data-workflow="orchestrate">Review, combine & fix</button><button class="btn" data-workflow="github-project">Check GitHub repository</button></div>`;}
export function connectionWorkflows(data){return `<section class="workflow-section"><h2>Named AI accounts</h2><p>Use separate sign-ins for Claude Max, Claude Pro, two Codex accounts, or multiple Cursor accounts. Choose the account on each task.</p><button class="btn primary" data-workflow="add-account">Add AI account</button><div class="profile-list">${(data.providerAccounts||[]).map(a=>`<article class="notice"><div><strong>${safe(a.name)}</strong><p>${safe(cliProviders.find(p=>p[0]===a.provider)?.[1])} · ${a.verified?'Verified':'Sign-in needed'}</p></div><button class="btn" data-workflow="account-login" data-profile-id="${a.id}">Sign in</button><button class="btn" data-workflow="account-verify" data-profile-id="${a.id}">Verify</button></article>`).join('')||'<p>No additional accounts yet. Your system sign-ins still work.</p>'}</div><h2>GitHub</h2><p>${data.github?.connected?'Connected as '+safe(data.github.login):'Connect GitHub CLI to access repositories and publish orchestrator results.'}</p><button class="btn" data-workflow="github-login">Sign in to GitHub</button><button class="btn primary" data-workflow="github-verify">Verify GitHub connection</button></section>`;}
export function projectWorkflowFields(data,p){return `<h3>Orchestrator</h3><label class="form-field"><span>Orchestrator provider</span><select name="orchestratorProvider">${cliProviders.map(([id,label])=>`<option value="${id}" ${(p.orchestratorProvider||'claude')===id?'selected':''}>${label}</option>`).join('')}</select></label>${accountField(data,p.orchestratorProvider||'claude',p.orchestratorAccountId,'orchestratorAccountId')}<label class="check"><input type="checkbox" name="autoOrchestrate" ${p.autoOrchestrate?'checked':''}>Automatically review and combine completed workers when this project’s active runs finish</label><p class="small muted">The orchestrator may use your provider subscription. It runs in its own branch and does not publish until you choose a GitHub action.</p><label class="form-field"><span>GitHub target branch (optional)</span><input name="githubBase" value="${safe(p.githubBase||'')}" placeholder="Repository default branch"></label>`;}
export function taskWorkflowControls(t){return `${t.status!=='running'?`<button class="btn" data-workflow="run-settings" data-task-id="${t.id}">Run settings</button>`:''}`+`${t.computerUse?`<div class="notice">Computer actions are reviewed by the Claude Code orchestrator.<button class="btn" data-workflow="revoke-computer" data-task-id="${t.id}">Revoke computer access</button></div>`:''}${t.kind==='orchestrate'&&['review','done'].includes(t.status)?`<div class="notice"><div><strong>Publish reviewed integration</strong><p>Commit this branch and choose how to publish it to GitHub.</p>${t.pullRequest?`<a href="${safe(t.pullRequest)}" target="_blank" rel="noopener noreferrer">Open pull request ↗</a>`:''}${t.publishError?`<p class="error">${safe(t.publishError)}</p>`:''}</div><button class="btn" data-workflow="publish" data-mode="push" data-task-id="${t.id}">Commit & push</button><button class="btn" data-workflow="publish" data-mode="pr" data-task-id="${t.id}">Create pull request</button><button class="btn primary" data-workflow="publish" data-mode="merge" data-task-id="${t.id}">Publish & merge PR</button></div>`:''}`;}
export async function workflowAction(el,c){
 const action=el.dataset.workflow;if(!action)return false;
 const {data,project,modal,request,refresh,close,toast,detail}=c;
 if(action==='run-ready'){const r=await request('/api/projects/'+project().id+'/run-ready','POST',{});await refresh();const started=r.results.filter(t=>t.started).length;modal('Workers started',`<p>${started} workers started concurrently. Each can implement its own section.</p>${r.results.filter(t=>t.error).map(t=>`<p>${safe(t.title)}: ${safe(t.error)}</p>`).join('')}`,`<button class="btn" data-action="close">Close</button>`);return true;}
 if(action==='run-settings'){
  const t=data.tasks.find(t=>t.id===el.dataset.taskId);
  modal('Run settings',`<form id="run-settings-form"><input type="hidden" name="id" value="${t.id}"><label class="form-field"><span>Worker</span><select name="provider">${cliProviders.map(([id,label])=>`<option value="${id}" ${t.provider===id?'selected':''}>${label}</option>`).join('')}</select></label>${accountField(data,t.provider,t.accountId)}<label class="form-field"><span>Model (Claude defaults to Sonnet)</span><input name="model" value="${safe(t.model||'')}" placeholder="sonnet, opus, or provider model ID"></label><label class="check"><input type="checkbox" name="readOnly" ${t.readOnly?'checked':''}>Read-only / planning (leave unchecked for workers that should make changes)</label><label class="form-field"><span>Explicit prerequisites (select only if this section cannot work independently)</span><select name="dependencies" multiple>${data.tasks.filter(x=>x.projectId===t.projectId&&x.id!==t.id).map(x=>`<option value="${x.id}" ${t.dependencies?.includes(x.id)?'selected':''}>${safe(x.title)}</option>`).join('')}</select></label><button type="button" class="btn" data-workflow="clear-prerequisites">Make independent</button><p>All workers can edit their own checkout. The orchestrator combines results and repairs integration problems afterward.</p></form>`,`<button class="btn" data-action="close">Cancel</button><button class="btn primary" data-workflow="save-run-settings">Save settings</button>`,true);return true;
 }
 if(action==='clear-prerequisites'){for(const o of document.querySelector('#run-settings-form [name=dependencies]').options)o.selected=false;return true;}
 if(action==='save-run-settings'){const f=new FormData(document.querySelector('#run-settings-form'));await request('/api/tasks/'+f.get('id'),'PATCH',{provider:f.get('provider'),accountId:f.get('accountId'),model:f.get('model'),readOnly:f.get('readOnly')==='on',dependencies:f.getAll('dependencies'),dependencyMode:'explicit'});close();await refresh();detail(f.get('id'));return true;}
 if(action==='remove-context'){await request('/api/projects/'+project().id+'/context/'+el.dataset.fileId,'DELETE',{});await refresh();return true;}
 if(action==='download-context'){const f=await request('/api/projects/'+project().id+'/context/'+el.dataset.fileId);const bytes=Uint8Array.from(atob(f.base64),c=>c.charCodeAt(0));const url=URL.createObjectURL(new Blob([bytes]));const a=document.createElement('a');a.href=url;a.download=f.name.split('/').pop();a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return true;}
 const cancel='<button class="btn" data-action="close">Cancel</button>';
 if(action==='add-account')modal('Add an AI account',`<form id="provider-account-form"><label class="form-field"><span>Provider</span><select name="provider">${cliProviders.filter(p=>p[0]!=='antigravity').map(([id,name])=>`<option value="${id}">${name}</option>`).join('')}</select></label><label class="form-field"><span>Account name</span><input name="name" placeholder="Claude Max, Claude Pro, Codex Work…"></label></form><p>Each account gets its own local sign-in profile. Sign in with the intended account in the browser opened by the provider.</p>`,`${cancel}<button class="btn primary" data-workflow="save-account">Create account profile</button>`);
 else if(action==='save-account'){const input=Object.fromEntries(new FormData(document.querySelector('#provider-account-form')));await request('/api/provider-accounts','POST',input);close();await refresh();toast('Account profile added. Sign in, then verify it.');}
 else if(action==='account-login'){const d=await request('/api/provider-accounts/'+el.dataset.profileId+'/login','POST',{openTerminal:true});modal('Provider sign-in opened',`<p>Complete sign-in in the PowerShell window, then return to Connections and verify this account.</p><pre class="log">${safe(d.command)}</pre>`,`<button class="btn" data-action="close">Done</button>`);}
 else if(action==='account-verify'){await request('/api/provider-accounts/'+el.dataset.profileId+'/verify','POST',{});await refresh();toast('Account verified');}
 else if(action==='github-login'){await request('/api/github/login','POST',{});toast('Complete GitHub sign-in in PowerShell, then click Verify.');}
 else if(action==='github-verify'){const d=await request('/api/github/status','POST',{});await refresh();toast(d.connected?'Connected to GitHub as '+d.login:d.message);}
 else if(action==='github-project'){const d=await request('/api/projects/'+project().id+'/github','POST',{});modal('GitHub repository',`<p><strong>${safe(d.nameWithOwner)}</strong></p><p>Default branch: ${safe(d.defaultBranchRef?.name)} · Your access: ${safe(d.viewerPermission)}</p>`,`<button class="btn" data-action="close">Close</button>`);}
 else if(action==='orchestrate'){
  const p=project(),sources=data.tasks.filter(t=>t.projectId===p.id&&!['orchestrate','plan'].includes(t.kind)&&t.worktree&&['review','done'].includes(t.status));
  modal('Review, combine & fix',`<p>The orchestrator reviews worker changes, combines them in a new branch, fixes conflicts and integration problems, and runs tests.</p><form id="orchestrator-form"><label class="form-field"><span>Orchestrator</span><select name="provider">${cliProviders.map(([id,label])=>`<option value="${id}" ${(p.orchestratorProvider||'claude')===id?'selected':''}>${label}</option>`).join('')}</select></label>${accountField(data,p.orchestratorProvider||'claude',p.orchestratorAccountId)}<div class="section-label">Completed work to combine</div>${sources.map(t=>`<label class="check"><input type="checkbox" name="sources" value="${t.id}" ${!t.integratedBy?'checked':''}>${safe(t.title)}${t.integratedBy?' · previously integrated':''}</label>`).join('')||'<p>Finish a coding task first.</p>'}<label class="check"><input type="checkbox" name="computerUse">Allow this orchestrator to request computer actions (orchestrator approves actions)</label></form>`,`${cancel}<button class="btn primary" data-workflow="start-orchestrator">Start orchestrator</button>`,true);
 }
 else if(action==='start-orchestrator'){const form=new FormData(document.querySelector('#orchestrator-form'));const sourceTaskIds=form.getAll('sources');if(!sourceTaskIds.length)throw new Error('Select completed work to combine.');const t=await request('/api/projects/'+project().id+'/orchestrate','POST',{provider:form.get('provider'),accountId:form.get('accountId'),sourceTaskIds,computerUse:form.get('computerUse')==='on'});close();await refresh();detail(t.id);}
 else if(action==='publish'){const d=await request('/api/tasks/'+el.dataset.taskId+'/publish','POST',{mode:el.dataset.mode});await refresh();detail(el.dataset.taskId);toast(d.merged?'Pull request merged':d.pullRequest?'Pull request ready':'Branch pushed');}
 else if(action==='revoke-computer'){await request('/api/tasks/'+el.dataset.taskId+'/revoke-computer','POST',{});await refresh();detail(el.dataset.taskId);toast('Computer access revoked');}
 else if(action==='computer-approvals')modal('Agent and computer approvals',`<p>Review the proposed command, edit, or computer action. Approval applies once to that request only.</p>${(data.computerRequests||[]).map(r=>`<article class="approval-request"><h3>${safe(r.title)} · ${safe(r.provider)}</h3><p><strong>${safe(r.tool)}</strong>: ${safe(r.args.reason)}</p><pre class="log">${safe(JSON.stringify(r.args,null,2))}</pre><button class="btn" data-workflow="deny-computer" data-request-id="${r.id}">Deny</button><button class="btn primary" data-workflow="approve-computer" data-request-id="${r.id}">Approve this action</button></article>`).join('')||'<p>No pending requests.</p>'}`,`<button class="btn" data-action="close">Close</button>`,true);
 else if(action==='approve-computer'||action==='deny-computer'){await request('/api/computer/requests/'+el.dataset.requestId,'POST',{approve:action==='approve-computer'});close();await refresh();toast(action==='approve-computer'?'Approval sent to agent':'Action denied');}
 return true;
}
export function contextUploads(p){return `<section class="context-panel"><h2>Shared files, images & folders</h2><p>Upload reference material for every agent. Folder uploads preserve their structure. Up to 25 MB per file and 100 MB per project. Empty folders are not included.</p><div class="upload-actions"><label class="btn">Upload files or images<input type="file" multiple data-context-upload hidden></label><label class="btn">Upload folder<input type="file" multiple webkitdirectory data-context-upload hidden></label></div><div>${(p.contextFiles||[]).map(f=>`<div class="notice"><span>${safe(f.name)} · ${Math.ceil(f.size/1024)} KB</span><button class="btn" data-workflow="download-context" data-file-id="${f.id}">Download</button><button class="btn" data-workflow="remove-context" data-file-id="${f.id}">Remove</button></div>`).join('')||'<p>No shared files uploaded yet.</p>'}</div></section>`;}
export async function uploadFiles(files,p,request,toast){
 const selected=[...files];let uploaded=0;
 for(const f of selected){
  if(f.size>25*1024*1024)throw new Error(`${f.name} exceeds 25 MB. ${uploaded} files uploaded.`);
  const base64=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=()=>reject(new Error('Could not read '+f.name));reader.readAsDataURL(f);});
  await request('/api/projects/'+p.id+'/context','POST',{name:f.webkitRelativePath||f.name,base64});uploaded++;toast(`Uploaded ${uploaded} / ${selected.length} files`);
 }
}
